// Script to check the database connection and count rows in the treatment_sessions table.
// (generated by Claude)

import 'dotenv/config';
import mariadb from 'mariadb';

const cfg = {
    host: process.env.DB_HOST,
    port: Number(process.env.DB_PORT),
    user: process.env.DB_USER,
    password: process.env.DB_PASSWORD,
    database: process.env.DB_NAME,
    connectionLimit: 5,
};

console.log('resolved config:', {
    ...cfg,
    password: cfg.password ? `<${cfg.password.length} chars>` : '(MISSING)',
});

const pool = mariadb.createPool(cfg);

try {
    const conn = await pool.getConnection();
    const rows = await conn.query('SELECT COUNT(*) AS n FROM treatment_sessions');
    console.log('SUCCESS:', rows);
    conn.release();
} catch (err) {
    console.error('--- FAILED ---');
    console.error('message :', err.message);
    console.error('code    :', err.code, '| errno:', err.errno, '| sqlState:', err.sqlState);
    console.error('cause   :', err.cause);
} finally {
    await pool.end();
}